17.4 Lifecycle + fetch


   ●  ●  ●   VUE
   <script setup>
   import { onMounted, ref } from "vue";

   const users = ref([]);
   const loading = ref(true);

   onMounted(async () => {
     try {
       const response = await fetch("http://localhost:8080/api/users");
       users.value = await response.json();
     } finally {
       loading.value = false;
     }
   });
   </script>


